const b = $input.first().json.body || $input.first().json;
const nome = b.cliente_nome || 'Cliente';
const tipo = b.tipo || 'serviço';
const prazo = b.prazo_prometido || 'a combinar';
const valorTotal = b.valor_total ? `R$ ${parseFloat(b.valor_total).toFixed(2)}` : '';
const valorEntrada = b.valor_entrada ? `\nEntrada recebida: R$ ${parseFloat(b.valor_entrada).toFixed(2)}` : '';
const telefone = (b.cliente_telefone || '').replace(/\D/g,'');
const automationId = '{{CLIENT_AUTOMATION_ID}}';

const texto = `Olá, ${nome}! Seu pedido foi registrado com sucesso.\n\nServiço: ${tipo}\nPrazo combinado: ${prazo}${valorTotal ? '\nValor total: '+valorTotal : ''}${valorEntrada}\n\nQualquer dúvida é só chamar!`;

return [{json: {
  telefone,
  texto,
  waInstance: '{{CLIENT_WA_INSTANCE}}',
  automationId,
  waUrl: `http://evolution_api:8080/message/sendText/{{CLIENT_WA_INSTANCE}}`,
  waKey: '{{CLIENT_EVOLUTION_API_KEY}}'
}}];

// Registra métrica de execução — alimenta dashboard do portal
const automationId = $('Preparar Mensagem').first().json.automationId;
if (!automationId) return $input.all();

// Métricas registradas no Supabase Graventum
return [{json: {
  automation_id: automationId,
  metric_key: 'pedidos_confirmados',
  metric_value: 1,
  metadata: {timestamp: new Date().toISOString()}
}}];
